css:
  .songa-thank-you-overlay {
    position: fixed;
    inset: 0;
    z-index: 999999;
    width: 100vw;
    height: 100vh;
    min-height: 100vh;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 24px;
    background: #f7f8fa;

    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
      Helvetica, Arial, sans-serif;
    color: #17202a;
  }

  .songa-thank-you-card {
    width: 100%;
    max-width: 520px;
    padding: 48px 40px;
    text-align: center;

    background: #ffffff;
    border: 1px solid #e8ebef;
    border-radius: 16px;
    box-shadow: 0 12px 40px rgba(23, 32, 42, 0.08);
  }

  .songa-thank-you-icon {
    width: 56px;
    height: 56px;
    margin: 0 auto 24px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: #f0f4f2;

    font-size: 24px;
  }

  .songa-thank-you-card h1 {
    margin: 0 0 14px;
    font-size: 30px;
    line-height: 1.2;
    font-weight: 600;
    letter-spacing: -0.5px;
  }

  .songa-thank-you-card p {
    margin: 0 auto;
    max-width: 420px;

    color: #66717d;
    font-size: 16px;
    line-height: 1.7;
  }

  .songa-thank-you-button {
    display: inline-block;
    margin-top: 30px;
    padding: 12px 22px;

    border-radius: 8px;
    background: #17202a;
    color: #ffffff;

    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
  }
  .songa-thank-you-button:hover{
    background: white;
    color: black;
    }

  .songa-thank-you-footer {
    margin-top: 32px;
    font-size: 12px;
    color: #9aa3ad;
  }

  @media (max-width: 480px) {
    .songa-thank-you-card {
      padding: 40px 24px;
    }

    .songa-thank-you-card h1 {
      font-size: 26px;
    }
  }
